const cnd = $('Infosimples · CND Federal').first().json.data?.[0] ?? null;
const est = $('Direct Data · CND Estadual').first().json.retorno ?? null;

let t_cnd = "Não obtida";
let t_pgfn = "Não verificado";
if (cnd) {
  const tipo = cnd.tipo || "";
  if (tipo.includes("efeitos de negativa")) t_cnd = "Positiva c/ efeitos de negativa";
  else if (tipo === "Positiva") t_cnd = "Positiva";
  else if (tipo === "Negativa") t_cnd = "Negativa";

  t_pgfn = "Não";
  if (cnd.debitos_pgfn === true) {
    t_pgfn = tipo.includes("efeitos de negativa") ? "Parcelada/garantida" : "Irregular";
  }
}

let t_est = "ND";
if (est) {
  t_est = (!est.possuiDebito || est.efeitoNegativa) ? "Regular" : "Irregular";
}

const gateDisparado = (t_cnd === "Positiva" && t_pgfn === "Irregular")
  ? "G3: CND federal positiva + PGFN irregular"
  : null;

return [{ json: { t_cnd, t_pgfn, t_est, gate_disparado: gateDisparado } }];
